DROP TABLE IF EXISTS names CASCADE;

CREATE TABLE names (
    locale text   NOT NULL,
    kind   text   NOT NULL,
    idx    int    NOT NULL,
    value  text   NOT NULL,
    PRIMARY KEY (locale, kind, idx)
);

DROP TABLE IF EXISTS dict_size CASCADE;

CREATE TABLE dict_size (
    locale text NOT NULL,
    kind   text NOT NULL,
    n      int  NOT NULL,
    PRIMARY KEY (locale, kind)
);

